# fit modular affine coordinates with margin patch-labels as demo evidence
D=[([(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)]), ([(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)]), ([(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(5,0,1),(5,11,0)]), ([(1,5,1),(2,0,1),(4,2,0)]), ([(1,0,0),(4,3,1)])]
# find rule based on row/col parity / combined coordinate mod n, report smallest errors
res=[]
for m in range(2,16):
 for a in range(m):
  for b in range(m):
   for k in range(m):
    err=sum(((a*r+b*c+k)%m==0)!=bool(y) for pts in D for r,c,y in pts)
    res.append((err,m,a,b,k))
print(sorted(res)[:12])

D=[
 ([(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)]), ([(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)]), ([(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(5,0,1),(5,11,0)]), ([(1,5,1),(2,0,1),(4,2,0)]), ([(1,0,0),(4,3,1)])]
solutions=[]
for a in range(-20,21):
 for b in range(-20,21):
  if not(a or b):continue
  for rev in (False,True):
   good=True; phases=[]
   for pts in D:
    so=sorted(pts,key=lambda x:(a*x[0]+b*x[1],x[0],x[1]),reverse=rev)
    # alternation condition
    phase=so[0][2]
    if any(x[2] != phase^(i%2) for i,x in enumerate(so)):good=False;break
    phases.append(phase)
   if good:solutions.append((a,b,rev,phases))
print(solutions[:30],len(solutions))

